const tokens = `-- name: Tokens :many
SELECT id,name,expires_at,created_at FROM access_tokens WHERE user_id=? AND expires_at>? AND name!='login' ORDER BY created_at DESC
`

type TokensParams struct {
	UserID    int64
	ExpiresAt float64
}

type TokensRow struct {
	ID        int64
	Name      string
	ExpiresAt float64
	CreatedAt float64
}

func (q *Queries) Tokens(ctx context.Context, db DBTX, arg TokensParams) ([]TokensRow, error) {
	rows, err := db.QueryContext(ctx, tokens, arg.UserID, arg.ExpiresAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TokensRow{}
	for rows.Next() {
		var i TokensRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.ExpiresAt,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

