const users = `-- name: Users :many
SELECT u.id,u.username,u.email,u.auth_kind,EXISTS(SELECT 1 FROM user_identities WHERE user_id=u.id),u.is_admin,u.created_at,u.updated_at,(SELECT COUNT(*) FROM folders f WHERE f.user_id=u.id),(SELECT COUNT(*) FROM favorites fv WHERE fv.user_id=u.id),(SELECT COUNT(*) FROM notification_settings ns WHERE ns.user_id=u.id AND ns.enabled=1) FROM users u ORDER BY u.id
`

type UsersRow struct {
	ID        int64
	Username  string
	Email     *string
	AuthKind  string
	Exists    bool
	IsAdmin   int64
	CreatedAt float64
	UpdatedAt float64
	Count     int64
	Count_2   int64
	Count_3   int64
}

func (q *Queries) Users(ctx context.Context, db DBTX) ([]UsersRow, error) {
	rows, err := db.QueryContext(ctx, users)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UsersRow{}
	for rows.Next() {
		var i UsersRow
		if err := rows.Scan(
			&i.ID,
			&i.Username,
			&i.Email,
			&i.AuthKind,
			&i.Exists,
			&i.IsAdmin,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Count,
			&i.Count_2,
			&i.Count_3,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
